import os

def scan_files(directory, exclude_dir_name):
    target_files = []
    for root, dirs, files in os.walk(directory):
        if os.path.abspath(root) == os.path.abspath(os.path.join(directory, exclude_dir_name)):
            continue
        for file in files:
            if file.endswith('.ini'):
                full_path = os.path.join(root, file)
                target_files.append(full_path)
    return target_files

directory_to_scan = "servisler"
exclude_name = "yedek"
files_to_process = scan_files(directory_to_scan, exclude_name)

def check_files(file_list):
    results = {}
    for file_path in file_list:
        with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
            lines = f.readlines()

        relevant_lines = []
        in_veritabani_section = False

        for line in lines:
            stripped = line.strip().lower()
            if stripped == '[veritabani]':
                in_veritabani_section = True
                relevant_lines.append(("SECTION_START", line))
            elif stripped.startswith('[') and stripped.endswith(']'):
                in_veritabani_section = False
                relevant_lines.append(("OTHER_SECTION", line))
            elif in_veritabani_section and stripped.startswith('port'):
                relevant_lines.append(("PORT_LINE", line))
            else:
                relevant_lines.append(("OTHER", line))

        results[file_path] = relevant_lines
    return results

current_state = check_files(files_to_process)

for file_path, lines in current_state.items():
    print(f"--- {file_path} ---")
    found_port = False
    for type, line in lines:
        if type == "PORT_LINE":
            print(f"  [BULUNDU] {line.strip()}")
            found_port = True
    if not found_port:
        print("  [PORT BULUNAMADI]")

import os
import re

def robust_verify(directory, exclude_dir_name, original_port="5432", new_port="6543"):
    print("--- Kapsamlı Doğrulama ---")

    target_files = []
    for root, dirs, files in os.walk(directory):
        if os.path.abspath(root) == os.path.abspath(os.path.join(os.getcwd(), directory, exclude_dir_name)):
            continue
        for file in files:
            if file.endswith('.ini'):
                target_files.append(os.path.join(root, file))

    yedek_dir = os.path.join(directory, exclude_dir_name)
    yedek_files = []
    for root, dirs, files in os.walk(yedek_dir):
        for file in files:
            if file.endswith('.ini'):
                yedek_files.append(os.path.join(root, file))

    all_good = True
    for f_path in target_files:
        with open(f_path, 'r', encoding='utf-8') as f:
            content = f.read()

        match = re.search(r'\[veritabani\]\s*([^\[]*)', content, re.IGNORECASE | re.DOTALL)
        if match:
            section_content = match.group(1)
            if re.search(r'port\s*=\s*' + original_port, section_content, re.IGNORECASE):
                if not re.search(r'port\s*=\s*' + new_port, section_content, re.IGNORECASE):
                    print(f"HATA: {f_path} - Eski port {original_port} hala mevcut!")
                    all_good = False
                else:
                    print(f"DOĞRULANDI: {f_path} - Port {original_port} -> {new_port} olarak güncellendi.")
            else:
                print(f"BİLGİ: {f_path} - [veritabani] içinde port {original_port} bulunamadı.")
        else:
            print(f"BİLGİ: {f_path} - [veritabani] bölümü bulunamadı.")

    for f_path in yedek_files:
        with open(f_path, 'r', encoding='utf-8') as f:
            content = f.read()
        if re.search(r'port\s*=\s*' + original_port, content, re.IGNORECASE):
            print(f"HATA: {f_path} (YEDEK) - Dosya değiştirilmiş!")
            all_good = False
        else:
            print(f"DOĞRULANDI: {f_path} (YEDEK) - Değişmedi.")

    return all_good

success = robust_verify("servisler", "yedek")
print(f"\nSonuç: {'BAŞARILI' if success else 'BAŞARISIZ'}")

